#include <stdio.h>
#include <string.h>

int L, C, P;
int black[8][8];
int isCand[8][8];
int cid[8][8];
int n;
int adj[40][40];
int matchR[40];
int used[40];

int dr[4] = {0, 0, -1, 1};
int dc[4] = {-1, 1, 0, 0};

int tryAug(int u) {
    for (int v = 0; v < n; v++) {
        if (adj[u][v] && !used[v]) {
            used[v] = 1;
            if (matchR[v] == -1 || tryAug(matchR[v])) {
                matchR[v] = u;
                return 1;
            }
        }
    }
    return 0;
}

int main(void) {
    scanf("%d %d", &L, &C);
    scanf("%d", &P);
    for (int i = 0; i < P; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        black[x][y] = 1;
    }

    /* candidate cells: not black, adjacent to at least one black */
    for (int r = 1; r <= L; r++) {
        for (int c = 1; c <= C; c++) {
            if (black[r][c]) continue;
            int ok = 0;
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr >= 1 && nr <= L && nc >= 1 && nc <= C && black[nr][nc]) {
                    ok = 1;
                    break;
                }
            }
            if (ok) {
                isCand[r][c] = 1;
                cid[r][c] = n++;
            }
        }
    }

    /* conflict graph between candidates that are adjacent */
    for (int r = 1; r <= L; r++) {
        for (int c = 1; c <= C; c++) {
            if (!isCand[r][c]) continue;
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr >= 1 && nr <= L && nc >= 1 && nc <= C && isCand[nr][nc]) {
                    adj[cid[r][c]][cid[nr][nc]] = 1;
                }
            }
        }
    }

    /* Konig: max independent set = n - max matching on bipartite graph.
       Grid adjacency is bipartite by parity: edges only between cells of
       opposite (r+c) parity. Use candidates of even parity as left side. */
    memset(matchR, -1, sizeof(matchR));
    int matching = 0;
    for (int r = 1; r <= L; r++) {
        for (int c = 1; c <= C; c++) {
            if (isCand[r][c] && ((r + c) % 2 == 0)) {
                memset(used, 0, sizeof(used));
                if (tryAug(cid[r][c])) matching++;
            }
        }
    }

    printf("%d\n", n - matching);
    return 0;
}
